/* ============================================
   RedRoom Fitness — Global Styles
   ============================================ */

/* CSS Variables */
:root {
  --red: #FF0000;
  --red-dark: #cc0000;
  --bg: #141414;
  --bg-light: #1a1a1a;
  --bg-lighter: #222222;
  --text: #FFFFFF;
  --text-muted: #AAAAAA;
  --text-dim: #888888;
  --border: #333333;
  --font-headline: 'Oswald', 'Bebas Neue', 'Impact', sans-serif;
  --font-body: 'Inter', 'Helvetica Neue', Helvetica, Arial, sans-serif;
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  background-color: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-headline);
  text-transform: uppercase;
  letter-spacing: 0.02em;
  line-height: 1.1;
}

/* ============================================
   Layout Utilities
   ============================================ */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

.section {
  padding: 80px 0;
}

.section-alt {
  background-color: var(--bg-light);
}

/* ============================================
   Buttons
   ============================================ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 14px 32px;
  font-family: var(--font-headline);
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  border-radius: 2px;
  transition: all var(--transition);
  min-height: 48px;
}

.btn-primary {
  background-color: var(--red);
  color: var(--text);
}

.btn-primary:hover {
  background-color: var(--red-dark);
  transform: translateY(-1px);
}

.btn-outline {
  background-color: transparent;
  color: var(--text);
  border: 2px solid var(--text);
}

.btn-outline:hover {
  background-color: var(--text);
  color: var(--bg);
}

.btn-large {
  padding: 18px 48px;
  font-size: 1.125rem;
}

/* ============================================
   Top Bar
   ============================================ */
.top-bar {
  background-color: var(--red);
  text-align: center;
  padding: 10px 16px;
  font-size: 0.875rem;
  font-weight: 500;
}

.top-bar a {
  text-decoration: underline;
  margin-left: 8px;
}

/* ============================================
   Navigation
   ============================================ */
.navbar {
  position: sticky;
  top: 0;
  z-index: 100;
  background-color: rgba(20, 20, 20, 0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}

.navbar-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.logo {
  font-family: var(--font-headline);
  font-size: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--red);
}

.logo span {
  color: var(--text);
}

.nav-links {
  display: flex;
  gap: 28px;
}

.nav-links a {
  font-size: 0.8rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
  transition: color var(--transition);
  position: relative;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text);
}

.nav-links a::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background-color: var(--red);
  transition: width var(--transition);
}

.nav-links a:hover::after,
.nav-links a.active::after {
  width: 100%;
}

.nav-utility {
  display: flex;
  align-items: center;
  gap: 16px;
}

.nav-utility a {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text);
  padding: 8px 14px;
  border: 1px solid var(--border);
  border-radius: 2px;
  transition: all var(--transition);
}

.nav-utility a:hover {
  border-color: var(--red);
  color: var(--red);
}

.nav-utility .btn-nav {
  background-color: var(--red);
  border-color: var(--red);
  color: var(--text);
}

.nav-utility .btn-nav:hover {
  background-color: var(--red-dark);
}

/* Mobile menu toggle */
.menu-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}

.menu-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background-color: var(--text);
  transition: all var(--transition);
}

/* ============================================
   Hero
   ============================================ */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #1a0505 0%, #141414 50%, #0a0a0a 100%);
}

.hero-bg::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, rgba(255, 0, 0, 0.08) 0%, transparent 70%);
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 900px;
  padding: 0 24px;
}

.hero h1 {
  font-size: clamp(2.5rem, 6vw, 5rem);
  margin-bottom: 20px;
  text-shadow: 0 2px 40px rgba(0,0,0,0.5);
}

.hero p {
  font-size: clamp(1rem, 2vw, 1.25rem);
  color: var(--text-muted);
  margin-bottom: 36px;
  max-width: 640px;
  margin-left: auto;
  margin-right: auto;
}

.hero-btns {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* ============================================
   Section Headers
   ============================================ */
.section-header {
  text-align: center;
  margin-bottom: 56px;
}

.section-header h2 {
  font-size: clamp(1.75rem, 4vw, 2.75rem);
  margin-bottom: 16px;
}

.section-header p {
  color: var(--text-muted);
  font-size: 1.05rem;
  max-width: 640px;
  margin: 0 auto;
}

/* ============================================
   Two Ways Cards
   ============================================ */
.two-ways-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
}

.way-card {
  background-color: var(--bg-lighter);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 48px 40px;
  transition: all var(--transition);
}

.way-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
}

.way-card h3 {
  font-size: 1.5rem;
  margin-bottom: 16px;
  color: var(--red);
}

.way-card p {
  color: var(--text-muted);
  line-height: 1.7;
}

/* ============================================
   Studio Experience
   ============================================ */
.studio-experience {
  text-align: center;
}

.studio-experience h2 {
  font-size: clamp(2rem, 5vw, 3.5rem);
  margin-bottom: 20px;
}

.studio-experience p {
  color: var(--text-muted);
  font-size: 1.1rem;
  max-width: 700px;
  margin: 0 auto 36px;
}

/* ============================================
   Free Trial CTA
   ============================================ */
.free-trial {
  background: linear-gradient(180deg, var(--bg-light) 0%, #1a0505 100%);
  text-align: center;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.free-trial h2 {
  font-size: clamp(2rem, 5vw, 3.5rem);
  margin-bottom: 28px;
}

/* ============================================
   Lifestyle Carousel
   ============================================ */
.carousel {
  position: relative;
  overflow: hidden;
  border-radius: 4px;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.carousel-slide {
  min-width: 100%;
  aspect-ratio: 16 / 9;
  background-color: var(--bg-lighter);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.carousel-slide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.carousel-slide .slide-caption {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 40px 24px 24px;
  background: linear-gradient(transparent, rgba(0,0,0,0.8));
  font-size: 1.1rem;
  font-weight: 500;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 48px;
  height: 48px;
  background-color: rgba(20, 20, 20, 0.7);
  border: 1px solid var(--border);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text);
  font-size: 1.25rem;
  transition: all var(--transition);
  z-index: 2;
}

.carousel-btn:hover {
  background-color: var(--red);
  border-color: var(--red);
}

.carousel-btn.prev { left: 16px; }
.carousel-btn.next { right: 16px; }

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 20px;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background-color: var(--border);
  transition: all var(--transition);
}

.carousel-dot.active {
  background-color: var(--red);
  width: 28px;
  border-radius: 5px;
}

/* ============================================
   Newsletter
   ============================================ */
.newsletter {
  text-align: center;
}

.newsletter h3 {
  font-size: 1.5rem;
  margin-bottom: 12px;
}

.newsletter p {
  color: var(--text-muted);
  margin-bottom: 28px;
}

.newsletter-form {
  display: flex;
  gap: 12px;
  justify-content: center;
  max-width: 520px;
  margin: 0 auto;
  flex-wrap: wrap;
}

.newsletter-form input {
  flex: 1;
  min-width: 240px;
  padding: 14px 18px;
  background-color: var(--bg-lighter);
  border: 1px solid var(--border);
  border-radius: 2px;
  color: var(--text);
  font-size: 1rem;
  transition: border-color var(--transition);
}

.newsletter-form input:focus {
  outline: none;
  border-color: var(--red);
}

.newsletter-form input::placeholder {
  color: var(--text-dim);
}

.newsletter-message {
  margin-top: 16px;
  font-size: 0.95rem;
  min-height: 24px;
}

.newsletter-message.success {
  color: #4ade80;
}

.newsletter-message.error {
  color: var(--red);
}

/* ============================================
   Footer
   ============================================ */
.footer {
  background-color: #0a0a0a;
  border-top: 1px solid var(--border);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}

.footer-col h4 {
  font-size: 0.875rem;
  margin-bottom: 20px;
  color: var(--text-muted);
  letter-spacing: 0.1em;
}

.footer-col ul li {
  margin-bottom: 12px;
}

.footer-col ul li a {
  color: var(--text-dim);
  font-size: 0.9rem;
  transition: color var(--transition);
}

.footer-col ul li a:hover {
  color: var(--text);
}

.country-select {
  position: relative;
}

.country-select-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  background-color: var(--bg-lighter);
  border: 1px solid var(--border);
  border-radius: 2px;
  color: var(--text);
  font-size: 0.875rem;
  width: 100%;
  justify-content: space-between;
}

.country-dropdown {
  position: absolute;
  bottom: 100%;
  left: 0;
  right: 0;
  background-color: var(--bg-lighter);
  border: 1px solid var(--border);
  border-radius: 2px;
  margin-bottom: 4px;
  overflow: hidden;
  opacity: 0;
  visibility: hidden;
  transform: translateY(4px);
  transition: all var(--transition);
  z-index: 10;
}

.country-dropdown.open {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.country-dropdown li {
  padding: 10px 16px;
  font-size: 0.875rem;
  color: var(--text-dim);
  cursor: pointer;
  transition: all var(--transition);
  margin: 0;
}

.country-dropdown li:hover {
  background-color: var(--bg);
  color: var(--text);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 24px;
  border-top: 1px solid var(--border);
  flex-wrap: wrap;
  gap: 16px;
}

.footer-bottom p {
  color: var(--text-dim);
  font-size: 0.8rem;
}

.footer-logo {
  font-family: var(--font-headline);
  font-size: 1.25rem;
  color: var(--red);
}

/* ============================================
   Workout Page — Toggle
   ============================================ */
.toggle-group {
  display: flex;
  justify-content: center;
  gap: 0;
  margin-bottom: 40px;
}

.toggle-btn {
  padding: 14px 36px;
  font-family: var(--font-headline);
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  background-color: var(--bg-lighter);
  border: 1px solid var(--border);
  color: var(--text-muted);
  transition: all var(--transition);
}

.toggle-btn:first-child {
  border-radius: 2px 0 0 2px;
}

.toggle-btn:last-child {
  border-radius: 0 2px 2px 0;
}

.toggle-btn.active {
  background-color: var(--red);
  border-color: var(--red);
  color: var(--text);
}

.toggle-btn:not(.active):hover {
  color: var(--text);
  border-color: var(--text-dim);
}

.toggle-content {
  display: none;
  animation: fadeIn 0.4s ease;
}

.toggle-content.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.toggle-panel {
  background-color: var(--bg-lighter);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 48px;
  text-align: center;
  max-width: 800px;
  margin: 0 auto;
}

.toggle-panel h3 {
  font-size: 1.75rem;
  margin-bottom: 16px;
  color: var(--red);
}

.toggle-panel p {
  color: var(--text-muted);
  font-size: 1.05rem;
  line-height: 1.7;
}

/* ============================================
   Workout Page — Schedule Table
   ============================================ */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 8px;
}

.schedule-table th,
.schedule-table td {
  padding: 18px 24px;
  text-align: left;
  border-bottom: 1px solid var(--border);
}

.schedule-table th {
  font-family: var(--font-headline);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  background-color: var(--bg-lighter);
}

.schedule-table td {
  font-size: 1rem;
  color: var(--text);
}

.schedule-table tr:hover td {
  background-color: rgba(255, 0, 0, 0.04);
}

.schedule-table td:first-child {
  font-weight: 600;
  color: var(--red);
}

/* ============================================
   Instructors — Filter & Grid
   ============================================ */
.filter-bar {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-bottom: 48px;
  flex-wrap: wrap;
}

.filter-pill {
  padding: 10px 22px;
  font-family: var(--font-body);
  font-size: 0.875rem;
  font-weight: 500;
  background-color: var(--bg-lighter);
  border: 1px solid var(--border);
  border-radius: 100px;
  color: var(--text-muted);
  transition: all var(--transition);
}

.filter-pill:hover,
.filter-pill.active {
  background-color: var(--red);
  border-color: var(--red);
  color: var(--text);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 28px;
}

.instructor-card {
  background-color: var(--bg-lighter);
  border: 1px solid var(--border);
  border-radius: 4px;
  overflow: hidden;
  transition: all var(--transition);
}

.instructor-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
}

.instructor-photo {
  width: 100%;
  aspect-ratio: 1;
  background: linear-gradient(135deg, #2a0a0a, #1a1a1a);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-headline);
  font-size: 3rem;
  color: var(--red);
  opacity: 0.6;
}

.instructor-info {
  padding: 24px;
}

.instructor-info h3 {
  font-size: 1.25rem;
  margin-bottom: 6px;
}

.instructor-info p {
  color: var(--text-muted);
  font-size: 0.9rem;
  margin-bottom: 16px;
}

.instructor-info a {
  font-family: var(--font-headline);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--red);
  transition: color var(--transition);
}

.instructor-info a:hover {
  color: var(--text);
}

.instructor-card.hidden {
  display: none;
}

/* ============================================
   FAQ Accordion
   ============================================ */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--border);
}

.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 0;
  font-family: var(--font-body);
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text);
  text-align: left;
  transition: color var(--transition);
}

.faq-question:hover {
  color: var(--red);
}

.faq-question .icon {
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform var(--transition);
  flex-shrink: 0;
  margin-left: 16px;
}

.faq-question .icon::before,
.faq-question .icon::after {
  content: '';
  position: absolute;
  background-color: currentColor;
  transition: all var(--transition);
}

.faq-question .icon::before {
  width: 14px;
  height: 2px;
}

.faq-question .icon::after {
  width: 2px;
  height: 14px;
}

.faq-item.open .faq-question .icon::after {
  transform: scaleY(0);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}

.faq-item.open .faq-answer {
  max-height: 400px;
  padding-bottom: 24px;
}

.faq-answer p {
  color: var(--text-muted);
  line-height: 1.7;
}

/* ============================================
   Digital Platform — Features
   ============================================ */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 32px;
}

.feature-card {
  background-color: var(--bg-lighter);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 40px 32px;
  transition: all var(--transition);
}

.feature-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
}

.feature-card h3 {
  font-size: 1.25rem;
  margin-bottom: 12px;
  color: var(--red);
}

.feature-card p {
  color: var(--text-muted);
  line-height: 1.7;
}

/* ============================================
   Responsive
   ============================================ */
@media (max-width: 1024px) {
  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .section {
    padding: 56px 0;
  }

  .nav-links {
    display: none;
    position: absolute;
    top: 64px;
    left: 0;
    right: 0;
    background-color: var(--bg);
    border-bottom: 1px solid var(--border);
    flex-direction: column;
    padding: 16px 24px;
    gap: 0;
  }

  .nav-links.open {
    display: flex;
  }

  .nav-links a {
    padding: 12px 0;
    border-bottom: 1px solid var(--border);
  }

  .nav-links a:last-child {
    border-bottom: none;
  }

  .menu-toggle {
    display: flex;
  }

  .nav-utility {
    display: none;
  }

  .two-ways-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .toggle-group {
    flex-direction: column;
    align-items: center;
  }

  .toggle-btn {
    width: 100%;
    max-width: 280px;
    border-radius: 2px !important;
  }

  .toggle-panel {
    padding: 32px 24px;
  }

  .schedule-table th,
  .schedule-table td {
    padding: 14px 16px;
    font-size: 0.9rem;
  }

  .hero-btns {
    flex-direction: column;
    align-items: center;
  }

  .hero-btns .btn {
    width: 100%;
    max-width: 280px;
  }

  .newsletter-form {
    flex-direction: column;
    align-items: center;
  }

  .newsletter-form input,
  .newsletter-form button {
    width: 100%;
    max-width: 320px;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 16px;
